fn env_truthy(name: &str) -> bool {
    matches!(
        std::env::var(name).ok().as_deref(),
        Some("1") | Some("true") | Some("yes") | Some("on")
    )
}

fn exact_geometry(d: &ExactDecision, call: ExactOperationCall) -> bool {
    d.op == call.op
        && d.dim == call.dim
        && d.batch == call.batch
        && d.c_in == call.c_in
        && d.c_out == call.c_out
        && d.spatial0 == call.spatial0
        && d.spatial1 == call.spatial1
        && d.weight_rank == call.weight_rank
        && d.weight0 == call.weight0
        && d.weight1 == call.weight1
        && d.weight2 == call.weight2
        && d.weight3 == call.weight3
        && d.groups == call.groups
        && d.kernel == call.kernel
        && d.stride == call.stride
        && d.padding == call.padding
        && d.output_padding == call.output_padding
        && d.dilation == call.dilation
        && d.dtype == call.dtype
}

// The only exact geometry selector. Status/proof/opt-in checks happen after it.
fn find_exact(call: ExactOperationCall) -> Option<&'static ExactDecision> {
    if env_truthy("CANDLE_ASD_EXACT_DISABLE")
        || !call.input_contiguous
        || call.input_start_offset != 0
        || !call.weight_contiguous
        || call.weight_start_offset != 0
    {
        return None;
    }
    DECISIONS.iter().find(|d| exact_geometry(d, call))
}

fn device_scope_ok(actual_uuid: Option<&str>) -> bool {
    TARGET_GPU_UUID.is_some() && actual_uuid == TARGET_GPU_UUID
}

fn proven(d: &'static ExactDecision) -> Option<ExactAsdMatch> {
    if d.evidence_ref == "unresolved" {
        return None;
    }
    let provider = execution_provider(d.backend)?;
    match (d.state, provider, d.implementation_id) {
        ("promoted", ExactExecutionProvider::RawCuda, "candle.grouped-transpose.raw.v1") => {
            if !env_truthy("CANDLE_ASD_V2_CT1D_ENABLE") {
                return None;
            }
        }
        ("promoted", ExactExecutionProvider::RawCuda, "candle.depthwise-conv2d-5x5.raw.v1") => {
            // Stage 2F closes the historical real-dispatch evidence for these four
            // exact points. Production lookup requires only the exact device scope.
        }
        ("promoted", ExactExecutionProvider::RawCuda, implementation_id) if implementation_id.starts_with("candle.sm61-exact-grouped.") => {
            // Stage 2E evidence binding promotes these exact rows. No positive opt-in
            // remains; the explicit kill-switch is retained for operational rollback.
            if env_truthy("CANDLE_SM61_EXACT_GROUPED_DISABLE") {
                return None;
            }
        }
        ("promoted", ExactExecutionProvider::Cudnn, implementation_id)
            if implementation_id.starts_with("candle.cudnn.") => {}
        // Reserved in the profile contract. A native decision is not emitted by the
        // current Stage2F adapter until an unambiguous native executor identity exists.
        ("promoted", ExactExecutionProvider::Native, _) => return None,
        _ => return None,
    }
    let profile_id = PROFILE_ID?;
    Some(ExactAsdMatch {
        profile_id,
        policy_id: profile_id,
        decision_id: d.id,
        state: d.state,
        execution_provider: provider,
        selected_backend: provider.as_str(),
        implementation_id: d.implementation_id,
        evidence_sha256: d.evidence_ref,
        min_integrated_speedup_x: d.min_integrated_speedup_x,
    })
}

fn unproven(d: &'static ExactDecision) -> Option<ExactUnprovenMatch> {
    if d.state != "validation_only_unproven"
        || execution_provider(d.backend) != Some(ExactExecutionProvider::RawCuda)
        || !d.implementation_id.starts_with("candle.sm61-exact-grouped.")
        || d.evidence_ref != "unresolved"
        || d.min_integrated_speedup_x.is_some()
        || !env_truthy("CANDLE_ASD_SM61_EXACT_GROUPED_ENABLE")
        || env_truthy("CANDLE_SM61_EXACT_GROUPED_DISABLE")
    {
        return None;
    }
    let profile_id = PROFILE_ID?;
    Some(ExactUnprovenMatch {
        profile_id,
        policy_id: profile_id,
        decision_id: d.id,
        state: d.state,
        execution_provider: ExactExecutionProvider::RawCuda,
        selected_backend: ExactExecutionProvider::RawCuda.as_str(),
        implementation_id: d.implementation_id,
        proof_status: "unresolved",
    })
}

// Stage 2F: the sole public production Exact Profile lookup.
pub fn lookup(call: ExactOperationCall, actual_uuid: Option<&str>) -> Option<ExactMatch> {
    if !device_scope_ok(actual_uuid) {
        return None;
    }
    let d = find_exact(call)?;
    if let Some(m) = proven(d) {
        return Some(ExactMatch::Proven(m));
    }
    unproven(d).map(ExactMatch::Unproven)
}
